}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 4, Name = "English", Abbreviation = "ENG" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" }
    ];

    private readonly List<Course> _courses;

    public CatalogService()
    {
        _courses =
        [
            new()
            {
                Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming",
                Description = "An introductory course covering fundamental programming concepts including variables, control structures, functions, and basic data structures using Python.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science",
                InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has 15 years of teaching experience. Her research focuses on programming language design and CS education.",
                IsFeatured = true
            },
            new()
            {
                Id = 2, CourseCode = "CS 301", Title = "Data Structures and Algorithms",
                Description = "Advanced study of data structures (trees, graphs, hash tables) and algorithm design techniques including divide-and-conquer, dynamic programming, and greedy algorithms.",
                Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", DepartmentId = 1, DepartmentName = "Computer Science",
                InstructorName = "Dr. James Rivera", InstructorBio = "Dr. Rivera is an ACM Distinguished Educator with publications in top algorithms conferences. Previously worked at Google Research.",
                IsFeatured = true
            },
            new()
            {
                Id = 3, CourseCode = "CS 450", Title = "Machine Learning",
                Description = "Covers supervised and unsupervised learning, neural networks, and practical applications of ML in real-world systems.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:30 PM", DepartmentId = 1, DepartmentName = "Computer Science",
                InstructorName = "Dr. Aisha Patel", InstructorBio = "Dr. Patel joined from industry where she led ML teams at a major tech company. She brings practical, project-based learning to the classroom.",
                IsFeatured = false
            },
            new()
            {
                Id = 4, CourseCode = "MATH 201", Title = "Linear Algebra",
                Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to science and engineering.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, DepartmentName = "Mathematics",
                InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is a mathematician specializing in applied linear algebra. He has authored two widely-used textbooks in the field.",
                IsFeatured = true
            },
            new()
            {
                Id = 5, CourseCode = "MATH 301", Title = "Differential Equations",
                Description = "First and second-order ODEs, systems of equations, Laplace transforms, and numerical methods with applications in physics and engineering.",
                Credits = 4, Schedule = "Tue/Thu 9:00–10:30 AM", DepartmentId = 2, DepartmentName = "Mathematics",
                InstructorName = "Dr. Maria Santos", InstructorBio = "Dr. Santos has a joint appointment in Mathematics and Engineering. Her research connects pure mathematics to real-world modeling problems.",
                IsFeatured = false
            },
            new()
            {
                Id = 6, CourseCode = "PHYS 101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions demonstrating fundamental physical principles.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM + Lab Thu 2:00–4:00 PM", DepartmentId = 3, DepartmentName = "Physics",
                InstructorName = "Dr. Thomas Wright", InstructorBio = "Dr. Wright is an award-winning educator passionate about making physics accessible. He runs the university's popular public science lecture series.",
                IsFeatured = true
            },
            new()
            {
                Id = 7, CourseCode = "PHYS 320", Title = "Quantum Mechanics",
                Description = "Introduction to quantum theory: wave functions, Schrödinger equation, angular momentum, spin, and hydrogen atom.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:30 PM", DepartmentId = 3, DepartmentName = "Physics",
                InstructorName = "Dr. Elena Novak", InstructorBio = "Dr. Novak is a theoretical physicist whose research in quantum information theory has been published in Nature and Physical Review Letters.",
                IsFeatured = false
            },
            new()
            {
                Id = 8, CourseCode = "ENG 110", Title = "College Writing",
                Description = "Develops essential writing skills through essay composition, peer review, revision strategies, and critical reading of diverse texts.",
                Credits = 3, Schedule = "Mon/Wed 10:00–11:30 AM", DepartmentId = 4, DepartmentName = "English",
                InstructorName = "Prof. Linda Howard", InstructorBio = "Prof. Howard is a published author and writing coach with 20 years of experience helping students find their voice.",
                IsFeatured = false
            },
            new()
            {
                Id = 9, CourseCode = "ENG 350", Title = "American Literature",
                Description = "Survey of major American literary works from the colonial period to the present, exploring themes of identity, freedom, and social change.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:30 PM", DepartmentId = 4, DepartmentName = "English",
                InstructorName = "Dr. Michael Okafor", InstructorBio = "Dr. Okafor specializes in African-American literature and has published extensively on the Harlem Renaissance.",
                IsFeatured = false
            },
            new()
            {
                Id = 10, CourseCode = "HIST 101", Title = "World History to 1500",
                Description = "Examines the development of civilizations from prehistory through the late medieval period, covering political, social, and cultural history.",
                Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 5, DepartmentName = "History",
                InstructorName = "Dr. Karen Walsh", InstructorBio = "Dr. Walsh is an archaeologist and historian whose fieldwork in the Mediterranean informs her engaging lecture style.",
                IsFeatured = true
            }
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.CourseCode).ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In production, this would persist to a database
        return request.CourseId > 0
            && !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId);
    }
}

