            <h4>Schedule</h4>
            <p>@_course.Schedule</p>

            <h4>Credits</h4>
            <p>@_course.Credits</p>

            <h4>Department</h4>
            <p>@_course.DepartmentName</p>
        </div>
        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Instructor</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@_course.InstructorName</h6>
                    <p class="card-text">@_course.InstructorBio</p>
                </div>
            </div>
            <div class="mt-3">
                <a href="enroll?courseId=@_course.Id" class="btn btn-success w-100">Request Enrollment</a>
            </div>
        </div>
    </div>
}

@code {
